#!/usr/bin/env python3
"""
Round 194o (culprits), 14 October 2026. Needs round 193o.

Every WBA benchmark but Urban, filed by subject.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ["## Round 194o (14 October)\n\nNeeds round 193o (guards on its heading). Tiles patch round194o_tiles.py\nbeside it. No app.js?v= bump.\n\n- WBA: the key works (wba_nature placed all 750 Nature Benchmark companies).\n  Tiles wba_nature.py now writes every benchmark in WBA's benchmarks dataset\n  the same way, wba/<benchmark>.geojson (Nature keeps nature_companies),\n  except the Urban Benchmark, which the owner left out. Ten new rows, filed\n  as the owner asked: Destruction: wba_ocean (Oceans > Companies scored on\n  their effect on the sea), wba_act (Climate > Companies scored on their\n  climate plans), with Nature where it was; Suppression: wba_gender_assessment\n  and wba_gender (Discrimination), wba_human_rights, wba_social,\n  wba_just_transition (new Physical suppression > Human rights and work:\n  companies scored), wba_food (The food and drink industries),\n  wba_digital_rights and wba_digital_inclusion (new Suppression by\n  information > Digital rights and access: companies scored).\n- Fix: 191o's Oceans > Tipping points heading had been put just after Every\n  human impact together, so the kinds of ocean harm fell under it; it now\n  sits at the end of Oceans.\n"]


DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round194o: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 193o" not in h.read_text(encoding="utf-8"):
        sys.exit("round194o: round 193o must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round194o: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round194o: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round194o: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
